CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(64) PRIMARY KEY, applied_at DATETIME(6) NOT NULL);
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','viewer') NOT NULL DEFAULT 'viewer', failed_logins INT NOT NULL DEFAULT 0, locked_until DATETIME(6) NULL, created_at DATETIME(6) NOT NULL);
CREATE TABLE IF NOT EXISTS current_state (signal_name VARCHAR(100) PRIMARY KEY, value_json JSON NOT NULL, source VARCHAR(50) NOT NULL, quality VARCHAR(30) NOT NULL, source_timestamp DATETIME(6) NOT NULL, received_timestamp DATETIME(6) NOT NULL);
CREATE TABLE IF NOT EXISTS telemetry (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, signal_name VARCHAR(100) NOT NULL, value_decimal DECIMAL(20,6) NULL, value_text VARCHAR(255) NULL, source VARCHAR(50) NOT NULL, quality VARCHAR(30) NOT NULL, source_timestamp DATETIME(6) NOT NULL, received_timestamp DATETIME(6) NOT NULL, INDEX idx_telemetry_signal_time(signal_name, source_timestamp));
CREATE TABLE IF NOT EXISTS commands (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, command_type VARCHAR(80) NOT NULL, payload_json JSON NOT NULL, status ENUM('pending','claimed','verified','failed','cancelled') NOT NULL DEFAULT 'pending', requested_by BIGINT UNSIGNED NULL, reason VARCHAR(500) NOT NULL, idempotency_key VARCHAR(100) NOT NULL UNIQUE, created_at DATETIME(6) NOT NULL, claimed_at DATETIME(6) NULL, completed_at DATETIME(6) NULL, error_message VARCHAR(500) NULL);
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor VARCHAR(100) NOT NULL, action VARCHAR(100) NOT NULL, object_type VARCHAR(100) NOT NULL, object_id VARCHAR(100) NULL, before_json JSON NULL, after_json JSON NULL, reason VARCHAR(500) NOT NULL, ip_address VARCHAR(45) NULL, correlation_id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, INDEX idx_audit_time(created_at));
CREATE TABLE IF NOT EXISTS prices (interval_start DATETIME(6) PRIMARY KEY, interval_end DATETIME(6) NOT NULL, area VARCHAR(8) NOT NULL, spot_dkk_kwh DECIMAL(12,6) NOT NULL, source VARCHAR(80) NOT NULL, fetched_at DATETIME(6) NOT NULL);
CREATE TABLE IF NOT EXISTS plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, generated_at DATETIME(6) NOT NULL, mode VARCHAR(20) NOT NULL, input_hash CHAR(64) NOT NULL, expected_saving_dkk DECIMAL(12,4) NOT NULL, explanation TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plan_intervals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, plan_id BIGINT UNSIGNED NOT NULL, starts_at DATETIME(6) NOT NULL, ends_at DATETIME(6) NOT NULL, action VARCHAR(30) NOT NULL, power_w INT NOT NULL, soc_before DECIMAL(5,2) NOT NULL, soc_after DECIMAL(5,2) NOT NULL, buy_price DECIMAL(10,5) NOT NULL, baseline_cost DECIMAL(12,5) NOT NULL, optimized_cost DECIMAL(12,5) NOT NULL, explanation VARCHAR(500) NOT NULL, confidence DECIMAL(4,3) NOT NULL, FOREIGN KEY(plan_id) REFERENCES plans(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS worker_heartbeats (worker VARCHAR(50) PRIMARY KEY, heartbeat_at DATETIME(6) NOT NULL, status VARCHAR(30) NOT NULL, details_json JSON NOT NULL);
